Payload = Annotated[FileSecret, {"description":"Synthetic deployment input"}]
def blueprint(payload: Payload):
    secret = payload
    entry = f'uv pip install --python /usr/local/bin/python3 --break-system-packages --quiet magnus-sdk==0.8.2\npython3 - <<\'LLP_PROBE\'\nimport hashlib,json,os,pathlib,subprocess,shutil,urllib.request\nimport magnus\np=magnus.download_file({secret!r},target_path="/magnus/workspace/payload.txt")\nassert pathlib.Path(p).read_text()=="LLP-AGI deployment roundtrip; no physics events.\\n"\nr={{"success":True,"tool":\'mma\',"sdk":magnus.__version__,"physics_events":0}}\nassert json.loads(urllib.request.urlopen(os.environ["MAGNUS_ADDRESS"]+"/health").read())["status"]=="ok"\nw=\'Get["FeynRules`"]; Print["LLP_DEPLOY_OK:",2+2,":",$Version,":",$FeynRulesVersion];\'\nc=subprocess.run(["wolframscript","-code",w],capture_output=True,text=True,timeout=120)\nassert c.returncode==0 and "LLP_DEPLOY_OK:4:" in c.stdout,(c.returncode,c.stdout,c.stderr)\nr["wolfram"]=c.stdout\nout=pathlib.Path("/magnus/workspace/probe.json")\nout.write_text(json.dumps(r,indent=2))\nsecret=magnus.custody_file(str(out),max_downloads=3)\npathlib.Path(os.environ["MAGNUS_RESULT"]).write_text(json.dumps({{"success":True,"output":secret}}))\n\nLLP_PROBE'
    submit_job(task_name="Deployment probe mma", namespace="HET-AGI", repo_name="ColliderAgent", branch="main", commit_sha="1140f39e8730889422a64a141fbd3ca10529e13b", container_image="docker://git.pku.edu.cn/het-agi/mma-het@sha256:0c396d087c394c1771d747fd00e895422ab585c1fda16642235e49caaf3a1e60", cpu_count=4, memory_demand="8G", system_entry_command='mounts=("/var/lib/docker/volumes/llp-agi-wolfram-license-20261016/_data:/root/.WolframEngine/Licensing")', entry_command=entry)
